package main

// SHIPPED COMPLETION SCRIPTS (U37).
//
// scripts/release-dist.sh puts completions/{pulse.bash,_pulse,pulse.fish}
// into every release archive, generated by scripts/release-completions.sh
// from a host build. TestCompletion_ShippedScriptsMatchLeaf drives that
// same generation script against this test binary (re-executed as the
// CLI via TestMain) and pins each file byte-equal to the leaf's output,
// with one file per shell CompletionShells() names.

import (
	"context"
	"os"
	"testing"
)

// runAsCLIEnv, when "1", makes the test binary act as the pulse CLI so a
// shell script under test can invoke it as PULSE without a build.
const runAsCLIEnv = "CMD_PULSE_TEST_RUN_AS_CLI"

func TestMain(m *testing.M) {
	if os.Getenv(runAsCLIEnv) == "1" {
		args := append([]string{"pulse"}, os.Args[1:]...)
		os.Exit(run(context.Background(), args, os.Stdout, os.Stderr))
	}
	os.Exit(m.Run())
}

// shippedCompletionFiles maps each supported shell to the file the
// release archives carry under completions/.
var shippedCompletionFiles = map[string]string{
	"bash": "pulse.bash",
	"zsh":  "_pulse",
	"fish": "pulse.fish",
}
